begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(10);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values ('18400000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp-cancel-prepare@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18400000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18400000-0000-0000-0000-000000000002','18400000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18400000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18400000-0000-0000-0000-000000000004','18400000-0000-0000-0000-000000000001','18400000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18400000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18400000-0000-0000-0000-000000000005','18400000-0000-0000-0000-000000000001','18400000-0000-0000-0000-000000000003',now());
insert into public.clients(id,organization_id,name) values ('18400000-0000-0000-0000-000000000006','18400000-0000-0000-0000-000000000002','Synthetic client');
insert into public.staffs(id,organization_id,name) values ('18400000-0000-0000-0000-000000000007','18400000-0000-0000-0000-000000000002','Synthetic staff');
insert into public.shifts(id,organization_id,client_id,start_at,end_at,status) values ('18400000-0000-0000-0000-000000000008','18400000-0000-0000-0000-000000000002','18400000-0000-0000-0000-000000000006','2026-11-01 00:00+00','2026-11-01 01:00+00','published');
insert into private.mcp_shift_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18400000-0000-0000-0000-000000000002',true,'{}','18400000-0000-0000-0000-000000000001',now());
insert into private.mcp_person_search_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18400000-0000-0000-0000-000000000002',true,'{}','18400000-0000-0000-0000-000000000001',now());
select set_config('request.jwt.claims','{"sub":"18400000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18400000-0000-0000-0000-000000000003","session_id":"18400000-0000-0000-0000-000000000005"}',true);
select ok(not has_function_privilege('mcp_import','private.prepare_mcp_shift_cancel(uuid,uuid,text,text)','execute') and not has_function_privilege('authenticated','private.prepare_mcp_shift_cancel(uuid,uuid,text,text)','execute'),'preparation remains private');
select throws_ok($$select private.prepare_mcp_shift_cancel('18400000-0000-0000-0000-000000000002','18400000-0000-0000-0000-000000000008','cancel','')$$,'42501','proposal_unavailable','disabled control rejects proposal');
insert into private.mcp_shift_cancel_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18400000-0000-0000-0000-000000000002',true,'{}','18400000-0000-0000-0000-000000000001',now());
select throws_ok($$select private.prepare_mcp_shift_cancel('18400000-0000-0000-0000-000000000099','18400000-0000-0000-0000-000000000008','cancel','')$$,'42501','mcp_shift_read_unavailable','other organization denied');
select throws_ok($$select private.prepare_mcp_shift_cancel('18400000-0000-0000-0000-000000000002','18400000-0000-0000-0000-000000000008','delete','')$$,'22023','invalid_shift_proposal','physical delete rejected');
select ok(private.prepare_mcp_shift_cancel('18400000-0000-0000-0000-000000000002','18400000-0000-0000-0000-000000000008','cancel','synthetic') is not null,'valid cancellation proposal saved');
select ok(private.prepare_mcp_shift_cancel('18400000-0000-0000-0000-000000000002','18400000-0000-0000-0000-000000000008','soft_delete','synthetic') is not null,'valid soft deletion proposal saved');
select is((select count(*) from private.mcp_shift_cancel_proposals),2::bigint,'invalid requests did not create proposals');
select is((select status from public.shifts where id='18400000-0000-0000-0000-000000000008'),'published','preparation does not modify the shift');
update public.organization_members set role='member' where organization_id='18400000-0000-0000-0000-000000000002' and user_id='18400000-0000-0000-0000-000000000001';
insert into public.organization_roles(id,organization_id,name,permissions) values ('18400000-0000-0000-0000-000000000010','18400000-0000-0000-0000-000000000002','View only','{"shifts":{"view":"all","edit":"none","delete":"none"}}');
insert into public.organization_member_roles(organization_id,user_id,role_id) values ('18400000-0000-0000-0000-000000000002','18400000-0000-0000-0000-000000000001','18400000-0000-0000-0000-000000000010');
select throws_ok($$select private.prepare_mcp_shift_cancel('18400000-0000-0000-0000-000000000002','18400000-0000-0000-0000-000000000008','cancel','')$$,'42501','proposal_unavailable','view-only member cannot prepare cancellation');
select throws_ok($$select private.prepare_mcp_shift_cancel('18400000-0000-0000-0000-000000000002','18400000-0000-0000-0000-000000000008','soft_delete','')$$,'42501','proposal_unavailable','view-only member cannot prepare deletion');
select * from finish();
rollback;
